import { expect, test } from "vite-plus/test";
import * as NodeModule from "node:module";
import { installStorage } from "./xhr-shim.ts";

// `message_keys` is generated by the Pebble build, so tests point require() at a stand-in.
const messageKeys = new URL("./message-keys.js", import.meta.url).href;
NodeModule.registerHooks({
  resolve: (specifier, context, nextResolve) =>
    specifier === "message_keys"
      ? { url: messageKeys, shortCircuit: true }
      : nextResolve(specifier, context),
});

// Each case needs a fresh module instance, and vite only allows literal dynamic imports.
const cases: Record<string, () => Promise<unknown>> = {
  machines: () => import("../src/pkjs/index.js?wizard=machines"),
  dirs: () => import("../src/pkjs/index.js?wizard=dirs"),
  providers: () => import("../src/pkjs/index.js?wizard=providers"),
  skipEffort: () => import("../src/pkjs/index.js?wizard=skip-effort"),
  projectEffort: () => import("../src/pkjs/index.js?wizard=project-effort"),
  launchError: () => import("../src/pkjs/index.js?wizard=launch-error"),
  stale: () => import("../src/pkjs/index.js?wizard=stale"),
};

async function setup(caseName: keyof typeof cases) {
  const handlers: Record<string, (event: any) => void> = {};
  const outbox: { message: any; success: () => void; failure: () => void }[] = [];
  const attempts: any[] = [];
  const calls: { name: string; args: any }[] = [];
  const held: FakeXhr[] = [];

  const script = {
    environment: { environmentId: "env-local", label: "Laptop" } as Record<string, any>,
    links: [] as any[],
    projectPages: {} as Record<number, { projects: any[]; nextCursor: number | null }>,
    capabilities: { providers: [] as any[] } as any,
    launch: { threadId: "thread-1" } as any,
    launchError: false,
    hold: null as string | null,
  };

  class FakeXhr {
    status = 0;
    responseText = "";
    response: unknown = null;
    responseType = "";
    timeout = 0;
    onload: (() => void) | null = null;
    onerror: (() => void) | null = null;
    ontimeout: (() => void) | null = null;
    url = "";
    body = "";
    private received = new Headers();

    open(_method: string, url: string) {
      this.url = url;
    }
    setRequestHeader() {}
    getResponseHeader(name: string) {
      return this.received.get(name);
    }
    send(body?: string | null) {
      this.body = body ?? "";
      respond(this);
    }
    json(payload: unknown, headers: Record<string, string> = {}) {
      this.status = 200;
      for (const [key, value] of Object.entries(headers)) this.received.set(key, value);
      this.responseText = JSON.stringify(payload);
      this.onload?.();
    }
    fail() {
      this.status = 500;
      this.responseText = "failed";
      this.onload?.();
    }
  }

  function resultFor(name: string, args: any) {
    switch (name) {
      case "t3_environment_read":
        return script.environment;
      case "t3_environment_links":
        return { links: script.links };
      case "t3_project_list":
        return script.projectPages[args.cursor ?? 0] ?? { projects: [], nextCursor: null };
      case "orchestrator_capabilities":
        return script.capabilities;
      case "t3_thread_launch":
        return script.launch;
      case "t3_thread_list":
        return { threads: [], nextCursor: null };
      case "t3_thread_read":
        return args.limit === 1
          ? { thread: { itemCount: 1 }, items: [] }
          : { items: [], thread: { status: "idle" } };
      default:
        return {};
    }
  }

  function respond(xhr: FakeXhr, force = false) {
    const request = JSON.parse(xhr.body || "{}");
    if (request.method === "notifications/initialized") {
      xhr.status = 202;
      xhr.onload?.();
      return;
    }
    if (request.method === "initialize") {
      xhr.json(
        { jsonrpc: "2.0", id: request.id, result: { protocolVersion: "2025-03-26" } },
        { "mcp-session-id": "session" },
      );
      return;
    }
    const name: string = request.params.name;
    calls.push({ name, args: request.params.arguments });
    if (name === script.hold && !force) {
      held.push(xhr);
      return;
    }
    if (name === "t3_thread_launch" && script.launchError) {
      xhr.fail();
      return;
    }
    xhr.json({ jsonrpc: "2.0", id: request.id, result: resultFor(name, request.params.arguments) });
  }

  const pebble = {
    addEventListener(name: string, callback: (event: any) => void) {
      handlers[name] = callback;
    },
    sendAppMessage(message: any, success: () => void, failure: () => void) {
      attempts.push(message);
      outbox.push({ message, success, failure });
    },
    openURL() {},
    showSimpleNotificationOnPebble() {},
  };

  const storage = installStorage({ mcpUrl: "https://test", mcpToken: "watch-token" });
  (globalThis as any).Pebble = pebble;
  (globalThis as any).XMLHttpRequest = FakeXhr;

  await cases[caseName]!();
  handlers.ready!({});

  const harness = {
    script,
    calls,
    attempts,
    held,
    newWizard() {
      handlers.appmessage!({ payload: { action: "new" } });
    },
    pick(step: string, item: string) {
      handlers.appmessage!({ payload: { action: "wizard_pick", thread: step, item } });
    },
    cancel() {
      handlers.appmessage!({ payload: { action: "close_wizard" } });
    },
    drain() {
      while (outbox.length) outbox.shift()!.success();
    },
    rows() {
      return attempts.filter((message) => message.action === "wizard_row");
    },
    steps() {
      return attempts.filter((message) => message.action === "wizard_step");
    },
    release() {
      for (const xhr of held.splice(0)) respond(xhr, true);
    },
    restore() {
      storage.restore();
      (globalThis as any).Pebble = undefined;
      (globalThis as any).XMLHttpRequest = undefined;
    },
  };

  harness.drain();
  calls.length = 0;
  attempts.length = 0;
  return harness;
}

test("lists this machine first and skips links that are not reachable", async () => {
  const harness = await setup("machines");
  try {
    harness.script.links = [
      { environmentId: "env-a", label: "Desktop", status: "reachable" },
      { environmentId: "env-b", label: "Old", status: "expired" },
      { environmentId: "env-c", label: "Gone", status: "unreachable" },
      { environmentId: "env-d", label: "", status: "reachable" },
    ];
    harness.newWizard();
    harness.drain();

    expect(harness.steps().map((step) => [step.thread, step.title])).toEqual([
      ["machine", "Machine"],
    ]);
    expect(harness.rows().map((row) => [row.title, row.item, row.harness])).toEqual([
      ["Laptop", "env-local", ""],
      ["Desktop", "env-a", ""],
      ["env-d", "env-d", ""],
    ]);
    expect(harness.attempts.at(-1).action).toBe("wizard_show");
  } finally {
    harness.restore();
  }
});

test("puts no-directory first, then project basenames across pages", async () => {
  const harness = await setup("dirs");
  try {
    harness.script.projectPages = {
      0: { projects: [{ id: "p1", workspaceRoot: "/code/alpha" }], nextCursor: 1 },
      1: { projects: [{ id: "p2", workspaceRoot: "/code/beta/" }], nextCursor: null },
    };
    harness.newWizard();
    harness.drain();
    harness.attempts.length = 0;

    harness.pick("machine", "env-local");
    harness.drain();

    expect(harness.steps().map((step) => step.title)).toEqual(["Project"]);
    expect(harness.rows().map((row) => [row.title, row.item])).toEqual([
      ["No directory", "__scratch__"],
      ["alpha", "p1"],
      ["beta", "p2"],
    ]);
    expect(
      harness.calls.filter((call) => call.name === "t3_project_list").map((call) => call.args),
    ).toEqual([
      { cursor: 0, limit: 100 },
      { cursor: 1, limit: 100 },
    ]);
  } finally {
    harness.restore();
  }
});

test("provider rows carry the driver kind and models come from the picked provider", async () => {
  const harness = await setup("providers");
  try {
    harness.script.capabilities = {
      providers: [
        {
          providerInstanceId: "inst-codex",
          driverKind: "codex",
          displayName: null,
          models: [{ id: "gpt-5", label: "GPT-5" }],
        },
        {
          providerInstanceId: "inst-claude",
          driverKind: "claude",
          displayName: "Claude",
          models: [{ id: "haiku" }],
        },
      ],
    };
    harness.newWizard();
    harness.drain();
    harness.pick("machine", "env-local");
    harness.drain();
    harness.attempts.length = 0;

    harness.pick("dir", "__scratch__");
    harness.drain();

    expect(harness.rows().map((row) => [row.title, row.item, row.harness])).toEqual([
      ["codex", "inst-codex", "codex"],
      ["Claude", "inst-claude", "claude"],
    ]);
    expect(harness.calls.find((call) => call.name === "orchestrator_capabilities")?.args).toEqual(
      {},
    );

    harness.attempts.length = 0;
    harness.pick("provider", "inst-claude");
    harness.drain();

    expect(harness.steps().map((step) => step.title)).toEqual(["Model"]);
    expect(harness.rows().map((row) => [row.title, row.item])).toEqual([["haiku", "haiku"]]);
  } finally {
    harness.restore();
  }
});

test("skips the effort step and launches a scratch thread when the model has no effort option", async () => {
  const harness = await setup("skipEffort");
  try {
    harness.script.capabilities = {
      providers: [
        {
          providerInstanceId: "inst-codex",
          driverKind: "codex",
          displayName: "Codex",
          models: [{ id: "gpt-5" }],
        },
      ],
    };
    harness.newWizard();
    harness.drain();
    harness.pick("machine", "env-local");
    harness.drain();
    harness.pick("dir", "__scratch__");
    harness.drain();
    harness.pick("provider", "inst-codex");
    harness.drain();
    harness.attempts.length = 0;

    harness.pick("model", "gpt-5");
    harness.drain();

    expect(harness.steps().some((step) => step.thread === "effort")).toBe(false);
    expect(harness.calls.find((call) => call.name === "t3_thread_launch")?.args).toEqual({
      title: "New thread",
      scratch: true,
      modelSelection: { instanceId: "inst-codex", model: "gpt-5" },
    });
    expect(harness.attempts.find((message) => message.action === "open_thread")).toMatchObject({
      thread: "thread-1",
      title: "New thread",
    });
    expect(harness.calls.some((call) => call.name === "t3_thread_list")).toBe(true);
  } finally {
    harness.restore();
  }
});

test("launches in the picked project with the chosen effort on a linked machine", async () => {
  const harness = await setup("projectEffort");
  try {
    harness.script.links = [{ environmentId: "env-a", label: "Desktop", status: "reachable" }];
    harness.script.projectPages = {
      0: { projects: [{ id: "p1", workspaceRoot: "/code/alpha" }], nextCursor: null },
    };
    harness.script.capabilities = {
      providers: [
        {
          providerInstanceId: "inst",
          driverKind: "codex",
          displayName: "Codex",
          models: [
            {
              id: "m",
              options: [
                { id: "reasoningEffort", values: ["low", "medium", "high"], default: "medium" },
              ],
            },
          ],
        },
      ],
    };
    harness.newWizard();
    harness.drain();
    harness.pick("machine", "env-a");
    harness.drain();
    expect(harness.calls.find((call) => call.name === "t3_project_list")?.args).toMatchObject({
      environmentId: "env-a",
    });
    harness.pick("dir", "p1");
    harness.drain();
    expect(
      harness.calls.find((call) => call.name === "orchestrator_capabilities")?.args,
    ).toMatchObject({ environmentId: "env-a" });
    harness.pick("provider", "inst");
    harness.drain();
    harness.attempts.length = 0;

    harness.pick("model", "m");
    harness.drain();
    expect(harness.steps().map((step) => step.title)).toEqual(["Effort"]);
    expect(harness.rows().map((row) => row.title)).toEqual(["low", "medium", "high"]);

    harness.pick("effort", "high");
    harness.drain();
    expect(harness.calls.find((call) => call.name === "t3_thread_launch")?.args).toEqual({
      environmentId: "env-a",
      projectId: "p1",
      title: "New thread",
      modelSelection: {
        instanceId: "inst",
        model: "m",
        options: [{ id: "reasoningEffort", value: "high" }],
      },
    });
  } finally {
    harness.restore();
  }
});

test("reports launch failures and keeps the wizard open", async () => {
  const harness = await setup("launchError");
  try {
    harness.script.capabilities = {
      providers: [
        {
          providerInstanceId: "inst",
          driverKind: "codex",
          displayName: "Codex",
          models: [{ id: "gpt-5" }],
        },
      ],
    };
    harness.newWizard();
    harness.drain();
    harness.pick("machine", "env-local");
    harness.drain();
    harness.pick("dir", "__scratch__");
    harness.drain();
    harness.pick("provider", "inst");
    harness.drain();
    harness.script.launchError = true;
    harness.attempts.length = 0;

    harness.pick("model", "gpt-5");
    harness.drain();

    expect(harness.attempts.find((message) => message.action === "wizard_error")?.title).toContain(
      "New thread failed",
    );
    expect(harness.attempts.some((message) => message.action === "open_thread")).toBe(false);

    harness.script.launchError = false;
    harness.attempts.length = 0;
    harness.pick("model", "gpt-5");
    harness.drain();
    expect(harness.attempts.find((message) => message.action === "open_thread")).toBeDefined();
  } finally {
    harness.restore();
  }
});

test("ignores wizard responses that arrive after a cancel or restart", async () => {
  const harness = await setup("stale");
  try {
    harness.newWizard();
    harness.drain();
    harness.script.hold = "t3_project_list";
    harness.attempts.length = 0;

    harness.pick("machine", "env-local");
    expect(harness.held).toHaveLength(1);
    harness.cancel();
    harness.script.hold = null;
    harness.release();
    harness.drain();
    expect(harness.attempts).toHaveLength(0);

    harness.attempts.length = 0;
    harness.script.hold = "t3_project_list";
    harness.newWizard();
    harness.drain();
    harness.pick("machine", "env-local");
    expect(harness.held).toHaveLength(1);
    harness.attempts.length = 0;
    harness.newWizard();
    harness.drain();
    harness.script.hold = null;
    harness.release();
    harness.drain();

    expect(harness.steps().map((step) => step.thread)).toEqual(["machine"]);
  } finally {
    harness.restore();
  }
});
